import{_ as i,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"Keynote: Supporting Swiss Academia with Ceph & OpenStack - Jens-Christian Fischer","description":"","frontmatter":{"title":"Keynote: Supporting Swiss Academia with Ceph & OpenStack - Jens-Christian Fischer","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","分布式存储","学术研究","OpenStack","Swisscom"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Keynote_-_Supporting_Swiss_Academia_with_Ceph_OpenStack_-_Jens-Christian_Fischer.md","filePath":"posts/2019/Keynote_-_Supporting_Swiss_Academia_with_Ceph_OpenStack_-_Jens-Christian_Fischer.md","lastUpdated":1780459816000}'),n={name:"posts/2019/Keynote_-_Supporting_Swiss_Academia_with_Ceph_OpenStack_-_Jens-Christian_Fischer.md"};function p(r,s,l,_,a,c){return e(),t("div",null,[...s[0]||(s[0]=[o("<p>在这次关键演讲中，Jens-Christian Fischer，来自Swiss Academic and Research Network (Swisscom) 的研发人员，分享了Swisscom在学术领域使用Ceph和OpenStack的经验。以下是会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划：</p><p><strong>会议关键细节</strong>：</p><ul><li><strong>Swisscom的角色</strong>： 作为国家研究教育网络，Swisscom负责提供服务和基础设施，支持学术机构和研究机构。</li><li><strong>Ceph集群的构建和运营</strong>： Swisscom分享了他们在构建和运营Ceph集群方面的经验，包括集群规模、存储容量和硬件升级。</li><li><strong>Ceph集群的问题解决</strong>： 讨论了Swisscom如何解决Ceph集群中遇到的问题，例如硬件故障、软件故障和网络问题。</li><li><strong>存储服务</strong>： 介绍了Swisscom如何利用Ceph提供文件存储、对象存储和块存储服务。</li><li><strong>学术研究应用</strong>： 分享了Swisscom在学术研究中的应用案例，如南极洲探险数据存储和分析。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>Ceph集群的规模和性能</strong>： 分享了Swisscom运营的Ceph集群规模和性能数据，以及硬件配置和存储容量。</li><li><strong>Ceph集群的稳定性</strong>： 强调了Ceph集群的稳定性，并分享了Swisscom如何解决集群中遇到的问题。</li><li><strong>Ceph集群的应用</strong>： 介绍了Swisscom如何利用Ceph提供各种存储服务，并分享了Ceph在学术研究中的应用案例。</li><li><strong>Ceph与其他存储系统的比较</strong>： 讨论了Ceph与其他存储系统的比较，并强调了Ceph的灵活性和可扩展性。</li></ul><p><strong>决定的事项</strong>：</p><ul><li>Swisscom将继续投资Ceph集群，并计划将虚拟机工作负载迁移到NVMe存储。</li><li>Swisscom将继续与学术机构和研究机构合作，推广Ceph在学术研究中的应用。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Swisscom将与其他Ceph用户分享其经验和最佳实践。</li><li>Swisscom将参加Ceph社区活动，并与其他Ceph用户交流。</li><li>Swisscom将继续开发新的存储服务，以满足学术机构和研究机构的需求。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>分布式存储</li><li>学术研究</li><li>研究教育网络</li><li>OpenStack</li><li>Swisscom</li><li>瑞士</li></ul>",11)])])}const C=i(n,[["render",p]]);export{S as __pageData,C as default};
